    X['a'] += -1.0 * np.einsum('IUAB,wVxU,xAwV,uBvI->uv', h['bb'][C,A,V,V], lambdas['ab'], t['ab'][pa,pV,ha,hA], t['ab'][pa,pV,ha,hC], optimize=True)
    X['a'] += -1.0 * np.einsum('IUAB,VWUX,XAIW,uBvV->uv', h['bb'][C,A,V,V], lambdas['bb'], t['bb'][pA,pV,hC,hA], t['ab'][pa,pV,ha,hA], optimize=True)
    X['a'] += 0.5 * np.einsum('IUAB,VWUX,XAVW,uBvI->uv', h['bb'][C,A,V,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], t['ab'][pa,pV,ha,hC], optimize=True)
