    X['bb'] += 0.125 * np.einsum('YZ,IJUV,ZJ,WXIY->WXUV', eta1['b'], h['bb'][C,C,A,A], t['b'][pA,hC], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 1.0 * np.einsum('YZ,IJUY,VI,WZJX->VWUX', eta1['b'], h['bb'][C,C,A,A], t['b'][pA,hC], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('YZ,IJUY,ZI,VWJX->VWUX', eta1['b'], h['bb'][C,C,A,A], t['b'][pA,hC], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.5 * np.einsum('YZ,IJUA,VAIY,WZJX->VWUX', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], t['bb'][pA,pA,hC,hA], optimize=True)
    X['bb'] += 0.25 * np.einsum('YZ,IJUA,VAWY,XZIJ->VXUW', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hA,hA], t['bb'][pA,pA,hC,hC], optimize=True)
    X['bb'] += 0.25 * np.einsum('YZ,IJUA,ZAJV,WXIY->WXUV', eta1['b'], h['bb'][C,C,A,V], t['bb'][pA,pV,hC,hA], t['bb'][pA,pA,hC,hA], optimize=True)
